package com.github.mdcdi1315.DotNetLayer.System.CodeDom.Compiler;

import com.github.mdcdi1315.DotNetLayer.System.Attribute;
import com.github.mdcdi1315.DotNetLayer.System.AttributeUsage;
import com.github.mdcdi1315.DotNetLayer.System.AttributeTargets;
import com.github.mdcdi1315.DotNetLayer.System.Diagnostics.CodeAnalysis.AllowNull;

import java.lang.annotation.Retention;
import java.lang.annotation.Documented;
import java.lang.annotation.RetentionPolicy;

/**
 * Identifies code generated by a tool.
 * This class cannot be inherited.
 */
@Attribute
@Documented
@Retention(RetentionPolicy.CLASS)
@AttributeUsage(AttributeTargets.All)
public @interface GeneratedCode
{
    /**
     * Gets the name of the tool that generated the code.
     * @return The name of the tool that generated the code.
     */
    @AllowNull
    String Tool();

    /**
     * Gets the version of the tool that generated the code.
     * @return The version of the tool that generated the code.
     */
    @AllowNull
    String Version();
}
